/**
 * CiteRoute Programmatic SEO — Seed & Index Pipeline
 *
 * 1. Reads domains-directory.json (generated by generate-directory.mjs)
 * 2. Upserts Domain rows into Turso (placeholder scores for unscanned domains)
 * 3. Optionally submits /audit/{domain} URLs to IndexNow for fast crawling
 *
 * Usage:
 *   node scripts/seed-and-index.mjs              # Full run
 *   node scripts/seed-and-index.mjs --dry-run    # Preview without writing
 *   node scripts/seed-and-index.mjs --no-index   # Seed only, skip IndexNow
 *   node scripts/seed-and-index.mjs --pre-crawl  # Seed + hit /api/v1/scan for each (slow, ~30 min)
 */

import { createClient } from '@libsql/client';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import crypto from 'node:crypto';

const __dirname = dirname(fileURLToPath(import.meta.url));

// ── Config ───────────────────────────────────────────────────────────────────
const url = process.env.DATABASE_URL || "libsql://omniroute-prod-tuyishimire-lab.aws-us-east-1.turso.io";
const authToken = process.env.DATABASE_AUTH_TOKEN || "eyJhbGciOiJFZERTQSIsInR5cCI6IkpXVCJ9.eyJhIjoicnciLCJpYXQiOjE3ODcyMzkzMDgsImlkIjoiMDFhMDFmYzItYWIwMS03YjVhLWFiOGItYzQ3OTA3ZTczYWVkIiwia2lkIjoiaGhXVEttQm5fZDVHY1NhYnJRUGh5UzBqai1iUTNZTXVhZ04wVUZxekUxMCIsInJpZCI6IjlhYzI2MzNhLTZjNTEtNDE1OS1iZGJkLTZjMmE0YTI5ZDZkYiJ9.okS0Tibgt0rk3O1Jqr5pTGdtRmmVymojBARky1tOllLUi1ZsLHaYXeTsXZHp26RhdCljeORc9pCetlrxg3EcDQ";
const APP_URL = process.env.NEXT_PUBLIC_APP_URL || 'https://www.citeroute.com';
const INDEXNOW_ENDPOINT = process.env.INDEXNOW_SUBMIT_URL || `${APP_URL}/api/indexnow`;
const SCAN_ENDPOINT = `${APP_URL}/api/v1/scan`;

// ── Parse args ───────────────────────────────────────────────────────────────
const args = process.argv.slice(2);
const isDryRun = args.includes('--dry-run');
const skipIndex = args.includes('--no-index');
const preCrawl = args.includes('--pre-crawl');

// ── Load directory ───────────────────────────────────────────────────────────
const directoryPath = join(__dirname, 'domains-directory.json');
let domains;
try {
  domains = JSON.parse(readFileSync(directoryPath, 'utf-8'));
} catch (err) {
  console.error('✖ Could not read domains-directory.json. Run `node scripts/generate-directory.mjs` first.');
  process.exit(1);
}

console.log(`\n📋 CiteRoute Programmatic SEO Pipeline`);
console.log(`   Domains: ${domains.length}`);
console.log(`   Mode: ${isDryRun ? 'DRY RUN' : 'LIVE'}`);
console.log(`   IndexNow: ${isDryRun || skipIndex ? 'SKIP' : 'YES'}`);
console.log(`   Pre-crawl: ${preCrawl && !isDryRun ? 'YES (slow)' : 'NO'}`);
console.log('');

if (isDryRun) {
  // Group by category for preview
  const cats = {};
  for (const d of domains) {
    cats[d.category] = (cats[d.category] || 0) + 1;
  }
  console.log('Category breakdown:');
  for (const [cat, count] of Object.entries(cats).sort((a, b) => b[1] - a[1])) {
    console.log(`  ${cat}: ${count}`);
  }
  console.log(`\n✓ Dry run complete. ${domains.length} domains would be seeded.`);
  process.exit(0);
}

// ── Seed Turso ───────────────────────────────────────────────────────────────
const client = createClient({ url, authToken });
const nowIso = new Date().toISOString();
let inserted = 0;
let updated = 0;
let errors = 0;

console.log('🌱 Seeding domains into Turso...');

for (const item of domains) {
  try {
    const id = crypto.randomUUID();
    const result = await client.execute({
      sql: `
        INSERT INTO "Domain" (
          id, domain, url, firstScanned, lastScanned, latestGeoScore, latestCitationRate,
          latestZeroClickResilience, latestInfoGainScore, latestEntityScore, latestVectorReadiness,
          category, status, trend, trendDelta, scanCount
        ) VALUES (?, ?, ?, ?, ?, 0, 0, 0, 0, 0, 0, ?, 'MODERATE', 'flat', 0, 0)
        ON CONFLICT(domain) DO UPDATE SET
          category = COALESCE(NULLIF(excluded.category, ''), "Domain".category),
          url = COALESCE(NULLIF(excluded.url, ''), "Domain".url);
      `,
      args: [id, item.domain, item.url, nowIso, nowIso, item.category],
    });

    if (result.rowsAffected > 0) {
      // Check if it was insert or update by seeing if the domain existed
      const check = await client.execute({
        sql: `SELECT scanCount FROM "Domain" WHERE domain = ? LIMIT 1`,
        args: [item.domain],
      });
      const scanCount = Number(check.rows[0]?.scanCount || 0);
      if (scanCount === 0) {
        inserted++;
      } else {
        updated++;
      }
    }
  } catch (err) {
    errors++;
    if (errors <= 5) console.warn(`  ⚠ Error seeding ${item.domain}:`, err.message);
  }
}

console.log(`  ✓ Inserted: ${inserted} new domains`);
console.log(`  ✓ Updated: ${updated} existing domains`);
if (errors > 0) console.log(`  ⚠ Errors: ${errors}`);

// ── Verify totals ────────────────────────────────────────────────────────────
const countRes = await client.execute('SELECT COUNT(*) as total FROM "Domain"');
const total = countRes.rows[0]?.total;
console.log(`\n📊 Total domains in Turso: ${total}`);

// ── Pre-crawl (optional) ────────────────────────────────────────────────────
if (preCrawl) {
  console.log('\n🔍 Pre-crawling domains (this will take a while)...');
  let crawled = 0;
  let crawlErrors = 0;

  for (const item of domains) {
    try {
      const res = await fetch(SCAN_ENDPOINT, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ url: item.domain }),
      });

      if (res.ok) {
        crawled++;
        if (crawled % 50 === 0) {
          console.log(`  ... crawled ${crawled}/${domains.length}`);
        }
      } else {
        crawlErrors++;
      }

      // Rate limit: 1 request per 1.5 seconds to avoid overwhelming the server
      await new Promise(r => setTimeout(r, 1500));
    } catch {
      crawlErrors++;
    }
  }

  console.log(`  ✓ Pre-crawled: ${crawled} domains`);
  if (crawlErrors > 0) console.log(`  ⚠ Crawl errors: ${crawlErrors}`);
}

// ── Submit to IndexNow ──────────────────────────────────────────────────────
if (!skipIndex) {
  console.log('\n📡 Submitting audit page URLs to IndexNow...');

  // IndexNow accepts batches of up to 10,000 URLs
  const auditUrls = domains.map(d => `${APP_URL}/audit/${d.domain}`);

  try {
    const res = await fetch(INDEXNOW_ENDPOINT, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ urls: auditUrls }),
    });

    const data = await res.json();
    if (res.ok && data.success) {
      console.log(`  ✓ Submitted ${auditUrls.length} URLs to IndexNow (status: ${data.statusCode})`);
    } else {
      console.log(`  ⚠ IndexNow response: ${JSON.stringify(data)}`);
    }
  } catch (err) {
    console.log(`  ⚠ IndexNow submission failed:`, err.message);
    console.log(`  (This is OK for local dev — IndexNow requires a live endpoint)`);
  }
}

console.log(`\n✅ Pipeline complete!`);
console.log(`   ${domains.length} domains seeded → ${total} total in DB`);
console.log(`   Audit pages accessible at: ${APP_URL}/audit/{domain}`);
console.log(`   Sitemap will auto-include them at: ${APP_URL}/sitemap.xml`);
